const server = submission.createLookupServer(options);
await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0, '127.0.0.1', resolve); });
let values;
try {
  const base = 'http://127.0.0.1:' + server.address().port;
  values = [];
  for (const [suffix, method] of [['/records?minScore=50','GET'], ['/missing','GET'], ['/records','POST'], ['/records?minScore=50x','GET'], ['/records?minScore=1&minScore=2','GET'], ['/records?unknown=1','GET']]) {
    const response = await fetch(base + suffix, { method, signal: AbortSignal.timeout(2000) });
    values.push({ status: response.status, value: await response.json(), allow: response.headers.get('allow') });
  }
} finally {
  server.closeAllConnections();
  await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}
observe({ values, listening: server.listening });
} finally {
  if (!dir.startsWith(root + sep)) throw new Error('Fixture escaped data root');
  await rm(dir, { recursive: true, force: true });
}

